import sys, yaml
data = yaml.safe_load(sys.stdin)
# Get all detect_remove and threshold experiments for the sensitivity curve
dr_exps = {}
for exp_id, exp in data.get('experiments', {}).items():
    if 'detect_remove' in exp_id or 'threshold_q' in exp_id:
        m = exp.get('metrics') or {}
        ppl = m.get('eval_ppl_holdout')
        dr_exps[exp_id] = {
            'status': exp.get('status'),
            'conclusion': exp.get('conclusion'),
            'ppl': ppl
        }

# Sort by experiment name
for k in sorted(dr_exps.keys()):
    v = dr_exps[k]
    print(f'{k}: status={v[\"status\"]}, conclusion={v[\"conclusion\"]}, PPL={v[\"ppl\"]}')
"

